# ============================================================
# Pearl Nest — Model 1 FDI Tooth Numbering Training Script
# ============================================================
#
# This script retrains Model 1 using Ultralytics YOLO for
# FDI tooth detection on panoramic dental X-rays.
#
# DATASET STRUCTURE REQUIRED:
#
#   dataset1/
#   ├── data.yaml          ← auto-generated by this script
#   ├── train/
#   │   ├── images/        ← panoramic X-ray images (.jpg/.png)
#   │   └── labels/        ← YOLO format label files (.txt)
#   └── val/
#       ├── images/
#       └── labels/
#
# LABEL FORMAT (YOLO):
#   Each .txt file has one line per tooth:
#     <class_id> <x_center> <y_center> <width> <height>
#   All values are normalized (0–1) relative to image size.
#
#   Class IDs map to FDI numbers:
#     0 -> FDI 11,  1 -> FDI 12, ..., 7 -> FDI 18
#     8 -> FDI 21,  9 -> FDI 22, ..., 15 -> FDI 28
#    16 -> FDI 31, 17 -> FDI 32, ..., 23 -> FDI 38
#    24 -> FDI 41, 25 -> FDI 42, ..., 31 -> FDI 48
#
# USAGE:
#   python train_model1.py                          # Full training
#   python train_model1.py --epochs 50 --batch 8    # Quick test run
#   python train_model1.py --resume                 # Resume interrupted training
#
# ============================================================

from __future__ import annotations

import argparse
import shutil
import sys
from pathlib import Path

import yaml


# ============================================================
# CONFIGURATION
# ============================================================

# FDI class mapping — must match your label files exactly
FDI_CLASSES = {
    0:  "11",  1:  "12",  2:  "13",  3:  "14",
    4:  "15",  5:  "16",  6:  "17",  7:  "18",
    8:  "21",  9:  "22",  10: "23",  11: "24",
    12: "25",  13: "26",  14: "27",  15: "28",
    16: "31",  17: "32",  18: "33",  19: "34",
    20: "35",  21: "36",  22: "37",  23: "38",
    24: "41",  25: "42",  26: "43",  27: "44",
    28: "45",  29: "46",  30: "47",  31: "48",
}

DATASET_DIR = Path("dataset1")
DATA_YAML = DATASET_DIR / "data.yaml"

# Existing model — used as pretrained weights for transfer learning
PRETRAINED_WEIGHTS = Path(r"runs\detect\train-3\weights\best.pt")

# Output directory for the new training run
PROJECT_DIR = Path("runs/detect")
RUN_NAME = "train-model1-retrained"


# ============================================================
# STEP 1 — VALIDATE DATASET STRUCTURE
# ============================================================

def validate_dataset(dataset_dir: Path) -> dict:
    """
    Check that the dataset folder has the right structure
    and count images/labels.
    """
    issues = []
    stats = {}

    for split in ("train", "val"):
        img_dir = dataset_dir / split / "images"
        lbl_dir = dataset_dir / split / "labels"

        if not img_dir.exists():
            issues.append(f"Missing: {img_dir}")
            continue
        if not lbl_dir.exists():
            issues.append(f"Missing: {lbl_dir}")
            continue

        images = list(img_dir.glob("*.jpg")) + list(img_dir.glob("*.png"))
        labels = list(lbl_dir.glob("*.txt"))

        # Check that each image has a matching label
        img_stems = {p.stem for p in images}
        lbl_stems = {p.stem for p in labels}

        missing_labels = img_stems - lbl_stems
        extra_labels = lbl_stems - img_stems

        stats[split] = {
            "images": len(images),
            "labels": len(labels),
            "missing_labels": len(missing_labels),
            "extra_labels": len(extra_labels),
        }

        if missing_labels:
            issues.append(
                f"{split}: {len(missing_labels)} images have no matching label file"
            )
            if len(missing_labels) <= 5:
                for stem in sorted(missing_labels):
                    issues.append(f"  -> {stem}")

    # Validate label content (check a sample)
    sample_labels = list((dataset_dir / "train" / "labels").glob("*.txt"))[:5]
    class_ids_seen = set()

    for lbl_file in sample_labels:
        for line_num, line in enumerate(lbl_file.read_text().splitlines(), 1):
            parts = line.strip().split()
            if len(parts) < 5:
                issues.append(
                    f"  {lbl_file.name}:{line_num} — "
                    f"expected 5 values, got {len(parts)}"
                )
                continue

            cls_id = int(parts[0])
            class_ids_seen.add(cls_id)

            if cls_id < 0 or cls_id > 31:
                issues.append(
                    f"  {lbl_file.name}:{line_num} — "
                    f"class_id {cls_id} out of range [0, 31]"
                )

            coords = [float(x) for x in parts[1:5]]
            for i, val in enumerate(coords):
                if val < 0 or val > 1:
                    issues.append(
                        f"  {lbl_file.name}:{line_num} — "
                        f"coordinate {i} = {val} (should be 0–1)"
                    )

    stats["class_ids_seen"] = sorted(class_ids_seen)

    return {"issues": issues, "stats": stats}


# ============================================================
# STEP 2 — GENERATE data.yaml
# ============================================================

def generate_data_yaml(dataset_dir: Path, output_path: Path):
    """
    Create the YOLO data.yaml configuration file.
    """
    data = {
        "path": str(dataset_dir.resolve()),
        "train": "train/images",
        "val": "val/images",
        "nc": 32,
        "names": FDI_CLASSES,
    }

    with open(output_path, "w", encoding="utf-8") as f:
        yaml.dump(data, f, default_flow_style=False, sort_keys=False)

    print(f"Generated: {output_path}")


# ============================================================
# STEP 3 — TRAINING
# ============================================================

def train(args):
    """Run YOLO training."""

    # Import here so validation can run without ultralytics
    from ultralytics import YOLO

    # Determine base weights
    if args.resume:
        # Resume from last checkpoint
        last_ckpt = PROJECT_DIR / RUN_NAME / "weights" / "last.pt"
        if not last_ckpt.exists():
            print(f"ERROR: Cannot resume — {last_ckpt} not found")
            sys.exit(1)
        print(f"Resuming from: {last_ckpt}")
        model = YOLO(str(last_ckpt))
        model.train(resume=True)
        return

    if args.from_scratch:
        # Train from a COCO-pretrained YOLOv8 base (no dental knowledge)
        base_model = args.yolo_base
        print(f"Training from scratch using: {base_model}")
        model = YOLO(base_model)
    else:
        # Transfer learning from the existing Model 1
        if PRETRAINED_WEIGHTS.exists():
            print(f"Transfer learning from: {PRETRAINED_WEIGHTS}")
            model = YOLO(str(PRETRAINED_WEIGHTS))
        else:
            print(f"WARNING: {PRETRAINED_WEIGHTS} not found")
            print(f"Falling back to: {args.yolo_base}")
            model = YOLO(args.yolo_base)

    # --- Training configuration ---
    train_args = {
        "data": str(DATA_YAML.resolve()),
        "epochs": args.epochs,
        "batch": args.batch,
        "imgsz": args.imgsz,
        "project": str(PROJECT_DIR),
        "name": RUN_NAME,
        "exist_ok": True,
        "patience": args.patience,
        "save_period": 10,           # Save checkpoint every 10 epochs
        "device": args.device,
        "workers": args.workers,
        "verbose": True,

        # --- Augmentation (tuned for dental X-rays) ---
        "hsv_h": 0.005,              # Minimal hue shift (X-rays are grayscale)
        "hsv_s": 0.1,                # Minimal saturation
        "hsv_v": 0.2,                # Moderate brightness variation
        "degrees": 5.0,              # Small rotation (teeth don't rotate much)
        "translate": 0.05,           # Small translation
        "scale": 0.3,                # Moderate scale variation
        "flipud": 0.0,               # NEVER flip vertically (jaw anatomy)
        "fliplr": 0.5,               # Horizontal flip OK (mirror symmetry)
        "mosaic": 0.5,               # Moderate mosaic
        "mixup": 0.0,                # No mixup (confuses tooth boundaries)

        # --- Loss weights ---
        "box": 7.5,                  # Standard box loss
        "cls": 1.5,                  # Increased class loss (FDI accuracy)
        "dfl": 1.5,                  # Distribution focal loss
    }

    # Optimizer selection
    if args.optimizer:
        train_args["optimizer"] = args.optimizer

    # Learning rate
    if args.lr:
        train_args["lr0"] = args.lr

    print("\n" + "=" * 60)
    print("TRAINING CONFIGURATION")
    print("=" * 60)
    for key, val in train_args.items():
        print(f"  {key}: {val}")
    print("=" * 60)

    # --- Start training ---
    results = model.train(**train_args)

    print("\n" + "=" * 60)
    print("TRAINING COMPLETE")
    print("=" * 60)

    best_path = PROJECT_DIR / RUN_NAME / "weights" / "best.pt"
    print(f"Best weights: {best_path.resolve()}")
    print(f"\nTo use the new model in Pearl Nest, update MODEL1_PATH in")
    print(f"perlnest_pipeline.py to:")
    print(f'  MODEL1_PATH = r"{best_path}"')

    return results


# ============================================================
# STEP 4 — QUICK VALIDATION
# ============================================================

def validate(args):
    """Run validation on the trained model."""
    from ultralytics import YOLO

    weights = Path(
    r"runs\detect\runs\detect\train-model1-retrained\weights\best.pt"
)
    if not weights.exists():
        print(f"ERROR: No trained weights at {weights}")
        sys.exit(1)

    print(f"Validating: {weights}")
    model = YOLO(str(weights))

    results = model.val(
        data=str(DATA_YAML.resolve()),
        imgsz=args.imgsz,
        batch=args.batch,
        device=args.device,
        verbose=True,
    )

    print("\n" + "=" * 60)
    print("VALIDATION RESULTS")
    print("=" * 60)
    print(f"  mAP@50:      {results.box.map50:.4f}")
    print(f"  mAP@50-95:   {results.box.map:.4f}")
    print(f"  Precision:    {results.box.mp:.4f}")
    print(f"  Recall:       {results.box.mr:.4f}")
    print("=" * 60)

    return results


# ============================================================
# STEP 5 — COMPARE OLD vs NEW MODEL
# ============================================================

def compare(args):
    """Compare old and new model on a test image."""
    import cv2
    from ultralytics import YOLO

    image_path = args.test_image
    image = cv2.imread(image_path)
    if image is None:
        print(f"ERROR: Cannot open {image_path}")
        sys.exit(1)

    old_weights = PRETRAINED_WEIGHTS
    new_weights = Path(
    r"runs\detect\runs\detect\train-model1-retrained\weights\best.pt"
)

    if not new_weights.exists():
        print(f"ERROR: New model not found at {new_weights}")
        sys.exit(1)

    output_dir = Path("runs/diagnostics/model1_comparison")
    output_dir.mkdir(parents=True, exist_ok=True)

    for label, weights_path in [("old", old_weights), ("new", new_weights)]:
        if not weights_path.exists():
            print(f"Skipping {label} model — weights not found")
            continue

        model = YOLO(str(weights_path))
        results = model.predict(
            source=image,
            imgsz=args.imgsz,
            conf=0.35,
            iou=0.45,
            verbose=False,
        )

        result = results[0]
        count = len(result.boxes) if result.boxes is not None else 0

        # Save annotated image
        out_path = output_dir / f"{label}_model_prediction.jpg"
        cv2.imwrite(str(out_path), result.plot())

        print(f"\n{label.upper()} MODEL ({weights_path.name}):")
        print(f"  Detections: {count}")

        if result.boxes is not None and count > 0:
            classes = result.boxes.cls.cpu().numpy().astype(int)
            confs = result.boxes.conf.cpu().numpy()
            names = result.names

            for cls_id, conf in sorted(
                zip(classes, confs),
                key=lambda x: -x[1]
            ):
                fdi = names.get(int(cls_id), str(cls_id))
                print(f"    FDI {fdi}  conf={conf:.2f}")

        print(f"  Saved: {out_path}")

    print(f"\nComparison images saved to: {output_dir.resolve()}")


# ============================================================
# MAIN
# ============================================================

def main():
    parser = argparse.ArgumentParser(
        description="Pearl Nest — Train Model 1 (FDI Tooth Numbering)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
EXAMPLES:

  # Validate dataset structure before training
  python train_model1.py check

  # Train with transfer learning from existing model (recommended)
  python train_model1.py train --epochs 100 --batch 16

  # Train from scratch (if existing model is too broken)
  python train_model1.py train --from-scratch --epochs 150

  # Resume interrupted training
  python train_model1.py train --resume

  # Validate the trained model
  python train_model1.py validate

  # Compare old vs new model on a test image
  python train_model1.py compare --test-image implant.jpg

DATASET STRUCTURE:

  dataset1/
  +-- train/
  |   +-- images/    (.jpg or .png X-ray images)
  |   +-- labels/    (.txt YOLO format labels)
  +-- val/
      +-- images/
      +-- labels/
        """,
    )

    subparsers = parser.add_subparsers(dest="command", help="Command to run")

    # --- check ---
    check_parser = subparsers.add_parser(
        "check", help="Validate dataset structure"
    )

    # --- train ---
    train_parser = subparsers.add_parser(
        "train", help="Train the model"
    )
    train_parser.add_argument(
        "--epochs", type=int, default=100,
        help="Number of training epochs (default: 100)"
    )
    train_parser.add_argument(
        "--batch", type=int, default=16,
        help="Batch size (default: 16, reduce if GPU OOM)"
    )
    train_parser.add_argument(
        "--imgsz", type=int, default=896,
        help="Training image size (default: 896)"
    )
    train_parser.add_argument(
        "--device", default="0",
        help="CUDA device (default: 0, use 'cpu' for CPU)"
    )
    train_parser.add_argument(
        "--workers", type=int, default=4,
        help="DataLoader workers (default: 4)"
    )
    train_parser.add_argument(
        "--patience", type=int, default=20,
        help="Early stopping patience (default: 20 epochs)"
    )
    train_parser.add_argument(
        "--from-scratch", action="store_true",
        help="Train from COCO pretrained base instead of transfer learning"
    )
    train_parser.add_argument(
        "--yolo-base", default="yolov8m.pt",
        help="Base YOLO model for from-scratch training (default: yolov8m.pt)"
    )
    train_parser.add_argument(
        "--resume", action="store_true",
        help="Resume training from last checkpoint"
    )
    train_parser.add_argument(
        "--optimizer", default=None,
        help="Optimizer: SGD, Adam, AdamW, etc."
    )
    train_parser.add_argument(
        "--lr", type=float, default=None,
        help="Initial learning rate"
    )

    # --- validate ---
    val_parser = subparsers.add_parser(
        "validate", help="Validate trained model"
    )
    val_parser.add_argument("--imgsz", type=int, default=896)
    val_parser.add_argument("--batch", type=int, default=16)
    val_parser.add_argument("--device", default="0")

    # --- compare ---
    cmp_parser = subparsers.add_parser(
        "compare", help="Compare old vs new model"
    )
    cmp_parser.add_argument(
        "--test-image", default="implant.jpg",
        help="Test image for comparison"
    )
    cmp_parser.add_argument("--imgsz", type=int, default=896)

    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        sys.exit(0)

    # ========================================================
    # CHECK
    # ========================================================

    if args.command == "check":
        print("=" * 60)
        print("DATASET VALIDATION")
        print("=" * 60)

        if not DATASET_DIR.exists():
            print(f"\nERROR: Dataset directory not found: {DATASET_DIR.resolve()}")
            print(f"\nPlease create the following structure:")
            print(f"  {DATASET_DIR}/")
            print(f"  +-- train/")
            print(f"  |   +-- images/   (put training X-rays here)")
            print(f"  |   +-- labels/   (put YOLO labels here)")
            print(f"  +-- val/")
            print(f"      +-- images/   (put validation X-rays here)")
            print(f"      +-- labels/   (put YOLO labels here)")
            sys.exit(1)

        result = validate_dataset(DATASET_DIR)

        if result["stats"]:
            for split, info in result["stats"].items():
                if split == "class_ids_seen":
                    continue
                print(f"\n  {split}:")
                print(f"    Images: {info['images']}")
                print(f"    Labels: {info['labels']}")
                if info["missing_labels"]:
                    print(f"    WARNING: Missing labels: {info['missing_labels']}")

            if "class_ids_seen" in result["stats"]:
                seen = result["stats"]["class_ids_seen"]
                print(f"\n  Class IDs found (sample): {seen}")
                print(f"  Expected: 0–31 (32 FDI classes)")
                if max(seen) > 31:
                    print(f"  WARNING: Class ID {max(seen)} exceeds 31!")

        if result["issues"]:
            print(f"\nWARNING: ISSUES FOUND ({len(result['issues'])}):")
            for issue in result["issues"]:
                print(f"  {issue}")
        else:
            print("\nOK: Dataset structure looks good!")

        # Generate data.yaml
        generate_data_yaml(DATASET_DIR, DATA_YAML)
        print(f"\nOK: Ready to train! Run:")
        print(f"  python train_model1.py train")

    # ========================================================
    # TRAIN
    # ========================================================

    elif args.command == "train":
        if not DATASET_DIR.exists():
            print(f"ERROR: Dataset not found at {DATASET_DIR.resolve()}")
            print(f"Run 'python train_model1.py check' first.")
            sys.exit(1)

        # Generate/update data.yaml
        generate_data_yaml(DATASET_DIR, DATA_YAML)

        # Validate before training
        result = validate_dataset(DATASET_DIR)
        if result["issues"]:
            print(f"WARNING: {len(result['issues'])} dataset issues found.")
            print("Run 'python train_model1.py check' for details.")
            response = input("Continue anyway? (y/n): ").strip().lower()
            if response != "y":
                sys.exit(0)

        # Backup existing best.pt
        if PRETRAINED_WEIGHTS.exists():
            backup = PRETRAINED_WEIGHTS.parent / "best_backup.pt"
            if not backup.exists():
                shutil.copy2(PRETRAINED_WEIGHTS, backup)
                print(f"Backed up existing model to: {backup}")

        train(args)

    # ========================================================
    # VALIDATE
    # ========================================================

    elif args.command == "validate":
        validate(args)

    # ========================================================
    # COMPARE
    # ========================================================

    elif args.command == "compare":
        compare(args)


if __name__ == "__main__":
    main()
